import type { ReactNode } from "react";

/**
 * Lede under an agent workbench tab. The tab strip already names the section —
 * this renders only the centered description and an optional trailing action.
 */
export function AgentTabIntro({
	description,
	action,
}: {
	description: string;
	action?: ReactNode;
}) {
	return (
		<div className="flex flex-wrap items-center justify-between gap-3">
			<p className="min-w-0 flex-1 text-center text-sm text-muted-foreground">
				{description}
			</p>
			{action ? <div className="shrink-0">{action}</div> : null}
		</div>
	);
}

