	if (tab === "skills") {
		return {
			to: "/$owner/agents/$agentId/skills",
			params: { owner, agentId },
		};
	}
	if (tab === "guardrails") {
		return {
			to: "/$owner/agents/$agentId/guardrails",
			params: { owner, agentId },
		};
	}
	if (tab === "permissions") {
		return {
			to: "/$owner/agents/$agentId/permissions",
			params: { owner, agentId },
		};
	}
	if (tab === "identity") {
		return {
			to: "/$owner/agents/$agentId/identity",
			params: { owner, agentId },
		};
	}
	return {
		to: "/$owner/agents/$agentId/settings",
		params: { owner, agentId },
	};
}
