import { useNavigate } from "@tanstack/react-router";
import type { ReactNode } from "react";
import { AgentGuardrailsCreate } from "@/components/agents/agent-guardrails-create";
import { AgentGuardrailsIndex } from "@/components/agents/agent-guardrails-index";
import { AgentPermissionsMatrix } from "@/components/agents/agent-permissions-matrix";
import { AgentSubpageShell } from "@/components/agents/agent-subpage-shell";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { useMembers } from "@/hooks/use-members";
import { useOrgContext } from "@/hooks/use-org-context";

/** One user-facing Guardrails surface, two sections. "safety" is the guardrail
 *  catalog (approvals + scanning policies); "access" hosts the deterministic
 *  permissions matrix. Storage and enforcement stay separate — this is
 *  presentation only. */
export type GuardrailsSection = "safety" | "access";

export function parseGuardrailsSection(value: unknown): GuardrailsSection {
	return value === "access" ? "access" : "safety";
}

function GuardrailsShell({
	owner,
	agentId,
	children,
	showBack,
}: {
	owner: string;
	agentId: string;
	children: ReactNode;
	showBack?: boolean;
}) {
	return (
		<AgentSubpageShell
			owner={owner}
			agentId={agentId}
			showBack={showBack}
			backLabel="Guardrails"
			backTo="/$owner/agents/$agentId/guardrails"
		>
			{children}
		</AgentSubpageShell>
	);
}

function GuardrailsSectionTabs({
	owner,
	agentId,
	section,
}: {
	owner: string;
	agentId: string;
	section: GuardrailsSection;
}) {
	const navigate = useNavigate();
	return (
		<Tabs
			value={section}
			onValueChange={(value) =>
				void navigate({
					to: "/$owner/agents/$agentId/guardrails",
					params: { owner, agentId },
					search:
						value === "access" ? { section: "access" as const } : {},
				})
			}
		>
			<TabsList>
				<TabsTrigger value="safety">Approvals &amp; Safety</TabsTrigger>
				<TabsTrigger value="access">Access</TabsTrigger>
			</TabsList>
		</Tabs>
	);
}

export function AgentGuardrailsIndexRoute({
	owner,
	agentId,
	section = "safety",
}: {
	owner: string;
	agentId: string;
	section?: GuardrailsSection;
}) {
	// The Access section reads/writes the org-scoped write-gate envelope; its
	// endpoints require org settings admin. Hide it from regular members so they
	// never land on a 403 error state (they'd have no way to load or save it).
	const { orgContext } = useOrgContext();
	const { isAdmin } = useMembers(orgContext.organizationId);
	const activeSection: GuardrailsSection = isAdmin ? section : "safety";
	return (
		<GuardrailsShell owner={owner} agentId={agentId}>
			<div className="space-y-4">
				{isAdmin ? (
					<GuardrailsSectionTabs
						owner={owner}
						agentId={agentId}
						section={activeSection}
					/>
				) : null}
				{activeSection === "access" ? (
					<AgentPermissionsMatrix owner={owner} agentId={agentId} />
				) : (
					<AgentGuardrailsIndex owner={owner} agentId={agentId} />
				)}
			</div>
		</GuardrailsShell>
	);
}

export function AgentGuardrailsCreateRoute({
	owner,
	agentId,
}: {
	owner: string;
	agentId: string;
}) {
	return (
		<GuardrailsShell owner={owner} agentId={agentId} showBack>
			<AgentGuardrailsCreate owner={owner} agentId={agentId} />
		</GuardrailsShell>
	);
}

export function AgentGuardrailDetailRoute({
	owner,
	agentId,
	name,
}: {
	owner: string;
	agentId: string;
	/** Still URL-encoded — decoded here before lookup. */
	name: string;
}) {
	const decodedName = decodeURIComponent(name);
	// The detail "page" is the guardrail list with the chosen row expanded in
	// place — deep-linkable, but it reads as the card opening inline.
	return (
		<GuardrailsShell owner={owner} agentId={agentId}>
			<AgentGuardrailsIndex
				owner={owner}
				agentId={agentId}
				expandedName={decodedName}
			/>
		</GuardrailsShell>
	);
}

