import { cleanup, render, screen } from "@testing-library/react";
import { afterEach, describe, expect, it } from "vitest";
import { vi } from "vitest";

vi.mock("@tanstack/react-router", async () => {
	const actual = await vi.importActual<
		typeof import("@tanstack/react-router")
	>("@tanstack/react-router");
	return { ...actual, useNavigate: () => vi.fn() };
});
vi.mock("@/components/agents/agent-guardrails-index", () => ({
	AgentGuardrailsIndex: () => <div data-testid="guardrails-list" />,
}));
vi.mock("@/components/agents/agent-guardrails-create", () => ({
	AgentGuardrailsCreate: () => null,
}));
vi.mock("@/components/agents/agent-permissions-matrix", () => ({
	AgentPermissionsMatrix: () => <div data-testid="permissions-matrix" />,
}));
vi.mock("@/hooks/use-org-context", () => ({
	useOrgContext: () => ({ orgContext: { organizationId: "org-1" } }),
}));
const membership = { isAdmin: true };
vi.mock("@/hooks/use-members", () => ({
	useMembers: () => membership,
}));

import { Route as PermissionsRoute } from "@/app/$owner/agents/$agentId/permissions";
import {
	AgentGuardrailsIndexRoute,
	parseGuardrailsSection,
} from "./agent-guardrails-route";

describe("parseGuardrailsSection", () => {
	it("accepts access and defaults everything else to safety", () => {
		expect(parseGuardrailsSection("access")).toBe("access");
		expect(parseGuardrailsSection("safety")).toBe("safety");
		expect(parseGuardrailsSection(undefined)).toBe("safety");
		expect(parseGuardrailsSection("bogus")).toBe("safety");
	});
});

describe("AgentGuardrailsIndexRoute sections", () => {
	afterEach(() => {
		cleanup();
		membership.isAdmin = true;
	});

	it("defaults to Approvals & Safety (the guardrail list)", () => {
		render(<AgentGuardrailsIndexRoute owner="acme" agentId="bot" />);
		expect(screen.getByTestId("guardrails-list")).toBeTruthy();
		expect(screen.queryByTestId("permissions-matrix")).toBeNull();
		expect(screen.getByText("Approvals & Safety")).toBeTruthy();
		expect(screen.getByText("Access")).toBeTruthy();
	});

	it("renders the permissions matrix under Access for admins", () => {
		render(
			<AgentGuardrailsIndexRoute owner="acme" agentId="bot" section="access" />,
		);
		expect(screen.getByTestId("permissions-matrix")).toBeTruthy();
		expect(screen.queryByTestId("guardrails-list")).toBeNull();
	});

	it("hides Access from non-admins and falls back to safety", () => {
		// The Access endpoints require org settings admin; regular members must
		// never land on a 403 state — even via a deep link.
		membership.isAdmin = false;
		render(
			<AgentGuardrailsIndexRoute owner="acme" agentId="bot" section="access" />,
		);
		expect(screen.getByTestId("guardrails-list")).toBeTruthy();
		expect(screen.queryByTestId("permissions-matrix")).toBeNull();
		expect(screen.queryByText("Access")).toBeNull();
	});
});

describe("legacy /permissions route", () => {
	it("redirects to Guardrails → Access so existing links keep working", () => {
		const params = { owner: "acme", agentId: "bot" };
		let thrown: unknown;
		try {
			// biome-ignore lint/suspicious/noExplicitAny: partial beforeLoad ctx
			PermissionsRoute.options.beforeLoad?.({ params } as any);
		} catch (error) {
			thrown = error;
		}
		expect(thrown).toBeTruthy();
		// TanStack redirect(): the thrown object carries the target options
		// (directly or under .options depending on version).
		const target = (thrown as { options?: Record<string, unknown> }).options ??
			(thrown as Record<string, unknown>);
		expect(target.to).toBe("/$owner/agents/$agentId/guardrails");
		expect(target.params).toEqual(params);
		expect(target.search).toEqual({ section: "access" });
	});
});

