import type { ReactNode } from "react";
import { AgentGuardrailsCreate } from "@/components/agents/agent-guardrails-create";
import { AgentGuardrailsIndex } from "@/components/agents/agent-guardrails-index";
import { AgentPermissionsMatrix } from "@/components/agents/agent-permissions-matrix";
import { AgentSubpageShell } from "@/components/agents/agent-subpage-shell";
import { useMembers } from "@/hooks/use-members";
import { useOrgContext } from "@/hooks/use-org-context";

function GuardrailsShell({
	owner,
	agentId,
	children,
	showBack,
}: {
	owner: string;
	agentId: string;
	children: ReactNode;
	showBack?: boolean;
}) {
	return (
		<AgentSubpageShell
			owner={owner}
			agentId={agentId}
			showBack={showBack}
			backLabel="Guardrails"
			backTo="/$owner/agents/$agentId/guardrails"
		>
			{children}
		</AgentSubpageShell>
	);
}

/** One user-facing Guardrails surface: the guardrail catalog (approvals +
 *  scanning policies) with the deterministic permissions matrix stacked below
 *  as an Access box. Storage and enforcement stay separate — this is
 *  presentation only. */
export function AgentGuardrailsIndexRoute({
	owner,
	agentId,
	expandedName,
}: {
	owner: string;
	agentId: string;
	/** When set, that guardrail's row is expanded in place to show its config. */
	expandedName?: string;
}) {
	// The Access box reads/writes the org-scoped write-gate envelope; its
	// endpoints require org settings admin. Hide it from regular members so they
	// never land on a 403 error state (they'd have no way to load or save it).
	const { orgContext } = useOrgContext();
	const { isAdmin } = useMembers(orgContext.organizationId);
	return (
		<GuardrailsShell owner={owner} agentId={agentId}>
			<div className="space-y-6">
				<AgentGuardrailsIndex
					owner={owner}
					agentId={agentId}
					expandedName={expandedName}
				/>
				{isAdmin ? (
					<section id="access" className="space-y-4 rounded-lg border p-4">
						<div>
							<h2 className="text-sm font-semibold">Access</h2>
							<p className="mt-1 text-xs text-muted-foreground">
								Deterministic permissions for what this agent can read, create,
								update, or delete. The guardrail policies above apply on top of
								these checks.
							</p>
						</div>
						<AgentPermissionsMatrix owner={owner} agentId={agentId} />
					</section>
				) : null}
			</div>
		</GuardrailsShell>
	);
}

export function AgentGuardrailsCreateRoute({
	owner,
	agentId,
}: {
	owner: string;
	agentId: string;
}) {
	return (
		<GuardrailsShell owner={owner} agentId={agentId} showBack>
			<AgentGuardrailsCreate owner={owner} agentId={agentId} />
		</GuardrailsShell>
	);
}

export function AgentGuardrailDetailRoute({
	owner,
	agentId,
	name,
}: {
	owner: string;
	agentId: string;
	/** Still URL-encoded — decoded here before lookup. */
	name: string;
}) {
	// The detail "page" is the guardrail list with the chosen row expanded in
	// place — deep-linkable, but it reads as the card opening inline.
	return (
		<AgentGuardrailsIndexRoute
			owner={owner}
			agentId={agentId}
			expandedName={decodeURIComponent(name)}
		/>
	);
}

import { createFileRoute } from "@tanstack/react-router";
import { AgentGuardrailsIndexRoute } from "@/components/agents/agent-guardrails-route";

export const Route = createFileRoute("/$owner/agents/$agentId/guardrails/")({
	component: AgentGuardrailsIndexPage,
});

function AgentGuardrailsIndexPage() {
	const { owner, agentId } = Route.useParams();
	return <AgentGuardrailsIndexRoute owner={owner} agentId={agentId} />;
}

import { createFileRoute, redirect } from "@tanstack/react-router";

// Permissions now lives in the Guardrails Access box (UI consolidation only —
// storage and enforcement are unchanged). Keep the old route as a redirect so
// existing links don't break.
export const Route = createFileRoute("/$owner/agents/$agentId/permissions")({
	beforeLoad: ({ params }) => {
		throw redirect({
			to: "/$owner/agents/$agentId/guardrails",
			params,
			hash: "access",
		});
	},
});

// @vitest-environment jsdom
import { cleanup, render, screen } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";

vi.mock("@tanstack/react-router", async () => {
	const actual = await vi.importActual<
		typeof import("@tanstack/react-router")
	>("@tanstack/react-router");
	return { ...actual, useNavigate: () => vi.fn() };
});
vi.mock("@/components/agents/agent-guardrails-index", () => ({
	AgentGuardrailsIndex: () => <div data-testid="guardrails-list" />,
}));
vi.mock("@/components/agents/agent-guardrails-create", () => ({
	AgentGuardrailsCreate: () => null,
}));
vi.mock("@/components/agents/agent-permissions-matrix", () => ({
	AgentPermissionsMatrix: () => <div data-testid="permissions-matrix" />,
}));
vi.mock("@/hooks/use-org-context", () => ({
	useOrgContext: () => ({ orgContext: { organizationId: "org-1" } }),
}));
const membership = { isAdmin: true };
vi.mock("@/hooks/use-members", () => ({
	useMembers: () => membership,
}));

import { Route as PermissionsRoute } from "@/app/$owner/agents/$agentId/permissions";
import { AgentGuardrailsIndexRoute } from "./agent-guardrails-route";

describe("AgentGuardrailsIndexRoute", () => {
	afterEach(() => {
		cleanup();
		membership.isAdmin = true;
	});

	it("stacks the Access box under the guardrail list for admins", () => {
		render(<AgentGuardrailsIndexRoute owner="acme" agentId="bot" />);
		expect(screen.getByTestId("guardrails-list")).toBeTruthy();
		expect(screen.getByTestId("permissions-matrix")).toBeTruthy();
		const heading = screen.getByRole("heading", { name: "Access" });
		// #access anchors the legacy /permissions redirect.
		expect(heading.closest("section")?.id).toBe("access");
	});

	it("hides the Access box from non-admins", () => {
		// The Access endpoints require org settings admin; regular members must
		// never land on a 403 state.
		membership.isAdmin = false;
		render(<AgentGuardrailsIndexRoute owner="acme" agentId="bot" />);
		expect(screen.getByTestId("guardrails-list")).toBeTruthy();
		expect(screen.queryByTestId("permissions-matrix")).toBeNull();
		expect(screen.queryByRole("heading", { name: "Access" })).toBeNull();
	});
});

describe("legacy /permissions route", () => {
	it("redirects to Guardrails #access so existing links keep working", () => {
		const params = { owner: "acme", agentId: "bot" };
		let thrown: unknown;
		try {
			// biome-ignore lint/suspicious/noExplicitAny: partial beforeLoad ctx
			PermissionsRoute.options.beforeLoad?.({ params } as any);
		} catch (error) {
			thrown = error;
		}
		expect(thrown).toBeTruthy();
		const target = (thrown as { options: Record<string, unknown> }).options;
		expect(target.to).toBe("/$owner/agents/$agentId/guardrails");
		expect(target.params).toEqual(params);
		expect(target.hash).toBe("access");
	});
});

