218	      return null;
219	    }
220	
221	    // Audit line: WHO got a lease for WHICH connection under WHICH deployment.
222	    // The token itself is never logged.
223	    logger.info(
224	      {
225	        agent_id: scope.agentId,
226	        connection_id: subject.connectionId,
227	        connector_key: subject.connectorKey,
228	        organization_id: subject.organizationId,
229	        install_id: install.id,
230	        deployment_name: scope.deploymentName,
231	        run_id: scope.runId,
