241	/**
242	 * Per-pod registry of {@link CredentialLeaseProvider}s keyed by provider. Mirrors
243	 * `InstallationTokenRegistry`: the single lookup point, so the resolver never
244	 * branches on a provider name.
245	 */
246	export class CredentialLeaseRegistry {
247	  private readonly providers = new Map<string, CredentialLeaseProvider>();
248	
249	  register(provider: CredentialLeaseProvider): void {
250	    this.providers.set(provider.provider, provider);
