33	/** The sandbox contribution of every eligible connection, already unioned. */
34	export interface ResolvedAgentTooling {
35	  /** Nix packages to union into the agent's `nixConfig.packages`. */
36	  packages: string[];
37	  /** Env vars to set in the worker environment. */
38	  env: Record<string, string>;
39	  /** Domains to grant on the worker's egress allowlist. */
40	  domains: string[];
41	}
42	
43	const EMPTY: ResolvedAgentTooling = {
44	  packages: [],
45	  env: {},
46	  domains: [],
47	};
