49	/** A connection row joined to its connector's declaration. */
50	interface ToolingConnectionRow {
51	  connection_id: string | number;
52	  connector_key: string;
53	  config: Record<string, unknown> | null;
54	  agent_tooling: unknown;
55	  auth_schema: unknown;
56	}
