58	/**
59	 * Validate a persisted `agent_tooling` value. The column is jsonb written by the
60	 * connector install path, so it is structurally untrusted at read time — a
61	 * malformed declaration must contribute nothing rather than inject a
62	 * non-string into the worker environment or the nix command line.
63	 *
64	 * Returns null when the value carries no usable contribution.
65	 */
66	export function parseAgentTooling(value: unknown): ConnectorAgentTooling | null {
67	  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
68	  const raw = value as Record<string, unknown>;
69	
70	  const packages = Array.isArray((raw.nix as Record<string, unknown>)?.packages)
71	    ? ((raw.nix as Record<string, unknown>).packages as unknown[]).filter(
72	        (pkg): pkg is string => {
73	          if (typeof pkg !== "string") return false;
74	          try {
75	            nixPackageAttrRef(pkg);
76	            return true;
77	          } catch {
78	            return false;
79	          }
80	        }
81	      )
82	    : [];
83	
84	  const env: ConnectorAgentToolingEnv[] = Array.isArray(raw.env)
85	    ? (raw.env as unknown[]).flatMap((entry) => {
86	        if (!entry || typeof entry !== "object") return [];
87	        const { name, credential } = entry as Record<string, unknown>;
88	        if (
89	          typeof name !== "string" ||
90	          name === "__proto__" ||
91	          !/^[A-Za-z_][A-Za-z0-9_]*$/.test(name)
92	        ) {
93	          return [];
94	        }
95	        // An unrecognized tier is dropped, not defaulted: defaulting to
96	        // 'placeholder' would silently route a lease var through the secret
97	        // store, and defaulting to 'lease' would mint for a provider that
98	        // cannot derive tokens. Neither is a safe guess.
99	        if (credential !== "lease" && credential !== "placeholder") return [];
100	        return [{ name, credential }];
101	      })
102	    : [];
103	
104	  const domains = Array.isArray(raw.domains)
105	    ? (raw.domains as unknown[]).filter(
106	        (d): d is string => typeof d === "string" && d.length > 0
107	      )
108	    : [];
109	
110	  if (packages.length === 0 && env.length === 0 && domains.length === 0) {
111	    return null;
112	  }
113	  return {
114	    ...(packages.length > 0 ? { nix: { packages } } : {}),
115	    ...(env.length > 0 ? { env } : {}),
116	    ...(domains.length > 0 ? { domains } : {}),
117	  };
118	}
