149	  organizationId: string;
150	}): Promise<string[]> {
151	  const domains = new Set<string>();
152	  for (const row of await loadToolingConnections(params.organizationId)) {
153	    const tooling = parseAgentTooling(row.agent_tooling);
154	    for (const domain of tooling?.domains ?? []) domains.add(domain);
