159	/**
160	 * Resolve every eligible connection's sandbox contribution for one deployment.
161	 *
162	 * Eligibility (v1): every ACTIVE, non-deleted connection in the agent's org
163	 * whose connector declares `agent_tooling`. `connections.agent_id` is not an
164	 * attachment boundary for data connectors; it is the fallback agent for chat
165	 * connections, so it must not scope this resolver.
166	 *
167	 * Failure is always "contribute nothing": a connection whose lease cannot be
168	 * minted drops its env var and the deployment proceeds. A sandbox with no
169	 * GH_TOKEN reports itself unauthenticated; a sandbox that failed to deploy tells
170	 * the user nothing.
171	 */
172	export async function resolveAgentTooling(params: {
173	  agentId: string;
174	  organizationId: string;
175	  deploymentName: string;
176	  leaseRegistry: CredentialLeaseRegistry;
177	  /**
178	   * Materializes a Tier-2 placeholder for `envName` on this deployment, or null
179	   * when it cannot. Supplied by the deployment manager (it owns the secret
180	   * store); a caller without one contributes lease vars only.
181	   */
182	  buildPlaceholder?: (params: {
183	    connectionId: number;
184	    connectorKey: string;
185	    envName: string;
186	  }) => Promise<string | null>;
187	  runId?: number;
188	}): Promise<ResolvedAgentTooling> {
189	  const { agentId, organizationId } = params;
190	  const rows = await loadToolingConnections(organizationId);
191	
192	  if (rows.length === 0) return EMPTY;
193	
194	  const packages = new Set<string>();
195	  const domains = new Set<string>();
196	  const env: Record<string, string> = {};
197	
198	  for (const row of rows) {
199	    const tooling = parseAgentTooling(row.agent_tooling);
200	    if (!tooling) {
201	      logger.warn(
202	        { connector_key: row.connector_key },
203	        "Ignoring malformed agent_tooling declaration"
204	      );
205	      continue;
206	    }
207	
208	    // Packages and domains are declaration-only: they describe what the CLI
209	    // needs to run at all, so they apply whether or not the credential resolves.
210	    // A `gh` on PATH that reports "not logged in" is a better failure than a
211	    // missing binary.
212	    for (const pkg of tooling.nix?.packages ?? []) packages.add(pkg);
213	    for (const domain of tooling.domains ?? []) domains.add(domain);
214	
215	    if (!tooling.env?.length) continue;
216	
217	    const connectionId = Number(row.connection_id);
218	    const scope: LeaseScopeHints = {
219	      agentId,
220	      deploymentName: params.deploymentName,
221	      runId: params.runId,
222	    };
223	
224	    for (const entry of tooling.env) {
225	      // First declaration wins. Two connections of the same connector (e.g. two
226	      // GitHub orgs) would otherwise fight over one env var and the sandbox
227	      // would silently use whichever sorted last.
228	      if (entry.name in env) {
229	        logger.info(
230	          {
231	            env_name: entry.name,
232	            connector_key: row.connector_key,
233	            connection_id: connectionId,
234	          },
235	          "Agent-tooling env var already contributed by an earlier connection — skipping"
236	        );
237	        continue;
238	      }
239	
240	      if (entry.credential === "lease") {
241	        const subject = buildLeaseSubject(row, connectionId, organizationId);
242	        const lease = await params.leaseRegistry.mintFor(subject, scope);
243	        if (!lease) continue;
244	        env[entry.name] = lease.token;
245	      } else if (params.buildPlaceholder) {
246	        const placeholder = await params.buildPlaceholder({
247	          connectionId,
248	          connectorKey: row.connector_key,
249	          envName: entry.name,
250	        });
251	        if (placeholder) env[entry.name] = placeholder;
252	      }
253	    }
254	  }
255	
256	  return {
257	    packages: [...packages],
258	    env,
259	    domains: [...domains],
260	  };
261	}
