268	function buildLeaseSubject(
269	  row: ToolingConnectionRow,
270	  connectionId: number,
271	  organizationId: string
272	): LeaseSubject {
273	  const config = parseJsonObject(row.config);
274	  const rawRef = config.installation_ref;
275	  const parsedRef =
