278	      : typeof rawRef === "string" && rawRef.trim()
279	        ? Number(rawRef)
280	        : null;
281	  const installationRef =
282	    parsedRef != null && Number.isFinite(parsedRef) ? parsedRef : null;
283	
284	  const method = getAppInstallationAuthMethods(
285	    normalizeConnectorAuthSchema(row.auth_schema)
286	  )[0];
