291	    connectorKey: row.connector_key,
292	    installationRef,
293	    provider: method?.provider ?? null,
294	    providerInstance: method?.providerInstance ?? null,
295	    appIdKey: method?.appIdKey ?? null,
296	    privateKeyKey: method?.privateKeyKey ?? null,
