62	/**
63	 * Validate a persisted `agent_tooling` value. The column is jsonb written by the
64	 * connector install path, so it is structurally untrusted at read time — a
65	 * malformed declaration must contribute nothing rather than inject a
66	 * non-string into the worker environment or the nix command line.
67	 *
68	 * Returns null when the value carries no usable contribution.
69	 */
70	export function parseAgentTooling(value: unknown): ConnectorAgentTooling | null {
71	  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
72	  const raw = value as Record<string, unknown>;
73	
74	  const packages = Array.isArray((raw.nix as Record<string, unknown>)?.packages)
75	    ? ((raw.nix as Record<string, unknown>).packages as unknown[]).filter(
76	        (pkg): pkg is string => {
77	          if (typeof pkg !== "string") return false;
78	          try {
79	            nixPackageAttrRef(pkg);
80	            return true;
81	          } catch {
82	            return false;
83	          }
84	        }
85	      )
86	    : [];
87	
88	  const env: ConnectorAgentToolingEnv[] = Array.isArray(raw.env)
89	    ? (raw.env as unknown[]).flatMap((entry) => {
90	        if (!entry || typeof entry !== "object") return [];
