100	        // 'placeholder' would silently route a lease var through the secret
101	        // store, and defaulting to 'lease' would mint for a provider that
102	        // cannot derive tokens. Neither is a safe guess.
103	        if (credential !== "lease" && credential !== "placeholder") return [];
