178	 * the user nothing.
179	 */
180	export async function resolveAgentTooling(params: {
181	  agentId: string;
182	  organizationId: string;
183	  deploymentName: string;
184	  leaseRegistry: CredentialLeaseRegistry;
185	  /**
186	   * Materializes a Tier-2 placeholder for `envName` on this deployment, or null
187	   * when it cannot. Supplied by the deployment manager (it owns the secret
188	   * store); a caller without one contributes lease vars only.
189	   */
190	  buildPlaceholder?: (params: {
191	    connectionId: number;
192	    connectorKey: string;
193	    envName: string;
194	  }) => Promise<string | null>;
195	  runId?: number;
196	}): Promise<ResolvedAgentTooling> {
197	  const { agentId, organizationId } = params;
198	  const rows = await loadToolingConnections(organizationId);
199	
200	  if (rows.length === 0) return EMPTY;
201	
202	  const packages = new Set<string>();
203	  const domains = new Set<string>();
204	  const env: Record<string, string> = {};
205	
206	  for (const row of rows) {
207	    const tooling = parseAgentTooling(row.agent_tooling);
208	    if (!tooling) {
209	      logger.warn(
210	        { connector_key: row.connector_key },
211	        "Ignoring malformed agent_tooling declaration"
212	      );
213	      continue;
214	    }
215	
216	    // Packages and domains are declaration-only: they describe what the CLI
217	    // needs to run at all, so they apply whether or not the credential resolves.
218	    // A `gh` on PATH that reports "not logged in" is a better failure than a
219	    // missing binary.
220	    for (const pkg of tooling.nix?.packages ?? []) packages.add(pkg);
221	    for (const domain of tooling.domains ?? []) domains.add(domain);
222	
223	    if (!tooling.env?.length) continue;
224	
225	    const connectionId = Number(row.connection_id);
226	    const scope: LeaseScopeHints = {
227	      agentId,
228	      deploymentName: params.deploymentName,
229	      runId: params.runId,
230	    };
231	
232	    for (const entry of tooling.env) {
233	      // First declaration wins. Two connections of the same connector (e.g. two
234	      // GitHub orgs) would otherwise fight over one env var and the sandbox
235	      // would silently use whichever sorted last.
236	      if (entry.name in env) {
237	        logger.info(
238	          {
239	            env_name: entry.name,
240	            connector_key: row.connector_key,
241	            connection_id: connectionId,
242	          },
243	          "Agent-tooling env var already contributed by an earlier connection — skipping"
244	        );
245	        continue;
246	      }
247	
248	      if (entry.credential === "lease") {
249	        const subject = buildLeaseSubject(row, connectionId, organizationId);
250	        const lease = await params.leaseRegistry.mintFor(subject, scope);
251	        if (!lease) continue;
252	        env[entry.name] = lease.token;
253	      } else if (params.buildPlaceholder) {
254	        const placeholder = await params.buildPlaceholder({
255	          connectionId,
256	          connectorKey: row.connector_key,
257	          envName: entry.name,
258	        });
259	        if (placeholder) env[entry.name] = placeholder;
260	      }
261	    }
262	  }
263	
264	  return {
265	    packages: [...packages],
266	    env,
267	    domains: [...domains],
268	  };
269	}
270	
271	/**
272	 * Build the lease subject from a connection row: its App-installation binding
273	 * (`config.installation_ref`) plus the connector method's declared provider and
274	 * gateway env-var NAMES. Never reads a credential.
275	 */
276	function buildLeaseSubject(
277	  row: ToolingConnectionRow,
278	  connectionId: number,
279	  organizationId: string
280	): LeaseSubject {
281	  const config = parseJsonObject(row.config);
282	  const rawRef = config.installation_ref;
283	  const parsedRef =
