285	      ? rawRef
286	      : typeof rawRef === "string" && rawRef.trim()
287	        ? Number(rawRef)
288	        : null;
289	  const installationRef =
290	    parsedRef != null && Number.isFinite(parsedRef) ? parsedRef : null;
