297	    connectionId,
298	    organizationId,
299	    connectorKey: row.connector_key,
300	    installationRef,
301	    provider: method?.provider ?? null,
302	    providerInstance: method?.providerInstance ?? null,
303	    appIdKey: method?.appIdKey ?? null,
304	    privateKeyKey: method?.privateKeyKey ?? null,
305	  };
306	}
