import fs from "node:fs"; import os from "node:os"; import path from "node:path";

const root = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), "lobu-sbx-")));
const mine = path.join(root, "workspaces", "agent-mine");
const theirs = path.join(root, "workspaces", "agent-theirs");
fs.mkdirSync(mine, { recursive: true });
fs.mkdirSync(theirs, { recursive: true });
fs.writeFileSync(path.join(theirs, "secret.txt"), "OTHER_TENANT_SECRET\n");

const checks: [string, boolean][] = [];
async function sh(cmd: string, env: Record<string, string | undefined>) {
  for (const [k, v] of Object.entries(env)) { if (v === undefined) delete process.env[k]; else process.env[k] = v; }
  const ops = await createEmbeddedBashOps({ workspaceDir: mine });
  const out: string[] = [];
  const r = await ops.exec(cmd, "/", { onData: (c: Buffer) => out.push(c.toString()), timeout: 20 });
  return { exit: r.exitCode, out: out.join("").trim() };
}

// REAL sandbox. No LOBU_ALLOW_UNSANDBOXED_EXEC, no bypass.
const SANDBOXED = {
  PATH: "/opt/homebrew/bin:/usr/bin:/bin",
  LOBU_EXEC_SANDBOX: "sandbox-exec",
  LOBU_ALLOW_UNSANDBOXED_EXEC: undefined,
  LOBU_POD_IS_SANDBOX: undefined,
  LOBU_WORKSPACE_BACKEND: undefined,
  NIX_PACKAGES: "gh",
};

const a = await sh("gh --version", SANDBOXED);
console.log("[declared gh, REAL sandbox]      exit=%d %s", a.exit, a.out.split("\n")[0].slice(0, 46));
checks.push(["declared gh runs under a real sandbox", a.exit === 0 && a.out.includes("gh version")]);

const b = await sh("git --version", SANDBOXED);
console.log("[undeclared git]                 exit=%d %s", b.exit, b.out.slice(0, 46));
checks.push(["undeclared binary blocked", b.exit !== 0]);

// The isolation property my bypass broke, now under the real sandbox.
const c = await sh(`cat ${path.join(theirs, "secret.txt")}`, SANDBOXED);
console.log("[read sibling workspace]         exit=%d %s", c.exit, c.out.slice(0, 46));
checks.push(["sibling workspace NOT readable", !c.out.includes("OTHER_TENANT_SECRET")]);

// And with NO sandbox, the safe default: 127 rather than an unsandboxed run.
const d = await sh("gh --version", { ...SANDBOXED, LOBU_EXEC_SANDBOX: "off" });
console.log("[no sandbox: safe default]       exit=%d %s", d.exit, d.out.slice(0, 46));
checks.push(["no sandbox => 127, never unsandboxed", d.exit !== 0]);

fs.rmSync(root, { recursive: true, force: true });
console.log("\n=== REAL-SANDBOX E2E (no bypass flags) ===");
let ok = true;
for (const [l, p] of checks) { console.log(`${p ? "PASS" : "FAIL"}  ${l}`); if (!p) ok = false; }
console.log("\nRESULT:", ok ? "PASS" : "FAIL");
process.exit(ok ? 0 : 1);
